from ta_moler.cmd.rtg_ctrl.linux.genericrtgctrllinux import GenericRtgCtrlLinux
import re
from moler.exceptions import ParsingDone, CommandFailure

__author__ = 'Dawid Gwizdz'
__copyright__ = 'Copyright (C) 2019, Nokia'
__email__ = 'dawid.gwizdz@nokia.com'


class Cpldmem(GenericRtgCtrlLinux):
    """Command for setting the counter."""

    def __init__(
            self, connection, address, value, options=None, prompt=None, newline_chars=None, runner=None):
        """
        Cpldmem command.

        :param options: parameter with which the command will be executed
        :param address: address with which the command will be executed
        :param value: value   with which the command will be executed
        :param connection: moler connection to device, terminal when command is executed.
        :param prompt: expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(Cpldmem, self).__init__(connection, prompt=prompt, newline_chars=newline_chars, runner=runner)
        self.options = options
        self.address = address
        self.value = value
        self.ret_required = False

    def build_command_string(self):
        """
        Build command string.

        :return: String representation of command to send over connection to device.
        """
        if self.options:
            cmd = f'cpldmem {self.options} {self.address} {self.value}'
        else:
            cmd = f'cpldmem {self.address} {self.value}'
        return cmd

    def on_new_line(self, line, is_full_line):
        """
        Put your parsing code here.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._parse_no_device(line)
            except ParsingDone:
                pass

        return super(Cpldmem, self).on_new_line(line, is_full_line)

    _re_no_device = re.compile(r"mmap: No such device")

    def _parse_no_device(self, line):
        """
        Parse line contains no such device error.

        :param line: Line from device.
        :return: None but raises ParsingDone if line has information to handle by this method.
        """
        if self._regex_helper.search(self._re_no_device, line):
            self.set_exception(CommandFailure(self, "mmap: No such device"))
            raise ParsingDone


